import React, { useState, useEffect, useRef } from 'react';

/* ── SVG Icons ── */
const IconHome = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 9.5L12 3l9 6.5V20a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9.5z"/>
    <polyline points="9 21 9 12 15 12 15 21"/>
  </svg>
);

const IconAI = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
    <circle cx="12" cy="12" r="4" fill="currentColor" opacity="0.3"/>
    <circle cx="12" cy="12" r="2" fill="currentColor"/>
  </svg>
);

const IconServices = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="3" y="3" width="7" height="7" rx="1"/>
    <rect x="14" y="3" width="7" height="7" rx="1"/>
    <rect x="14" y="14" width="7" height="7" rx="1"/>
    <rect x="3" y="14" width="7" height="7" rx="1"/>
  </svg>
);

const IconAbout = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10"/>
    <line x1="12" y1="16" x2="12" y2="12"/>
    <line x1="12" y1="8" x2="12.01" y2="8"/>
  </svg>
);

const IconGlobe = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#777"
    strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10"/>
    <line x1="2" y1="12" x2="22" y2="12"/>
    <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>
  </svg>
);

const navLinks = [
  { label: 'Accueil', Icon: IconHome, target: '#accueil' },
  { label: 'Djamano ai', Icon: IconAI, target: '#ai' },
  { label: 'Services', Icon: IconServices, target: '#services' },
  { label: 'A propos', Icon: IconAbout, target: '#apropos' },
];

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const [langModalOpen, setLangModalOpen] = useState(false);
  const [currentLang, setCurrentLang] = useState('FR');
  const modalRef = useRef(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (modalRef.current && !modalRef.current.contains(event.target)) {
        setLangModalOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleScrollTo = (target) => {
    const element = document.querySelector(target);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const s = {
    nav: {
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 1000,
      background: 'rgba(255,255,255,0.97)', backdropFilter: 'blur(12px)',
      borderBottom: '1px solid #f0f0f0',
      boxShadow: scrolled ? '0 2px 24px rgba(0,0,0,0.07)' : 'none',
      transition: 'box-shadow .3s', fontFamily: 'Poppins, sans-serif',
    },
    inner: { maxWidth: 1200, margin: '0 auto', padding: '0 32px', height: 66, display: 'flex', alignItems: 'center', justifyContent: 'space-between' },
    logo: { display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', background: 'none', border: 'none' },
    logoCircle: { width: 34, height: 34, borderRadius: '50%', background: '#FF5A00', display: 'flex', alignItems: 'center', justifyContent: 'center' },
    logoText: { fontSize: 20, fontWeight: 800, color: '#111', letterSpacing: '-0.5px' },
    links: { display: 'flex', alignItems: 'center', gap: 8 },
    link: {
      display: 'inline-flex', alignItems: 'center', gap: 7, padding: '8px 16px',
      borderRadius: 20, fontSize: 13.5, fontWeight: 500, color: '#555',
      background: 'none', border: 'none', cursor: 'pointer', transition: 'all .2s'
    },
    right: { display: 'flex', alignItems: 'center', gap: 16, position: 'relative' },
    globeBtn: {
      display: 'flex', alignItems: 'center', gap: 4, background: '#f5f5f5',
      border: 'none', padding: '6px 12px', borderRadius: 20, cursor: 'pointer',
      transition: 'all .2s'
    },
    globeText: { fontSize: 12, fontWeight: 600, color: '#555' },
    modal: {
      position: 'absolute', top: '42px', right: 0, background: '#fff',
      borderRadius: 12, border: '1px solid #ebebeb', boxShadow: '0 10px 30px rgba(0,0,0,0.08)',
      padding: '6px', display: 'flex', flexDirection: 'column', gap: 2, minWidth: 80, zIndex: 1001
    },
    modalOpt: (active) => ({
      padding: '8px 14px', fontSize: 13, fontWeight: 600, borderRadius: 8,
      textAlign: 'center', cursor: 'pointer', transition: 'all .15s',
      background: active ? '#FFF3ED' : 'transparent',
      color: active ? '#FF5A00' : '#444',
      border: 'none', width: '100%'
    })
  };

  return (
    <nav style={s.nav}>
      <div style={s.inner}>
        <button style={s.logo} onClick={() => handleScrollTo('#accueil')}>
          <div style={s.logoCircle}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3"><path d="M12 2L2 12h3v8h6v-6h2v6h6v-8h3L12 2z"/></svg>
          </div>
          <span style={s.logoText}>Djamano</span>
        </button>

        <div style={s.links}>
          {navLinks.map(({ label, Icon, target }) => (
            <button key={label} style={s.link} onClick={() => handleScrollTo(target)}>
              <Icon />
              <span style={{ textTransform: 'capitalize' }}>{label}</span>
            </button>
          ))}
        </div>

        <div style={s.right} ref={modalRef}>
          <button style={s.globeBtn} onClick={() => setLangModalOpen(!langModalOpen)}>
            <IconGlobe />
            <span style={s.globeText}>{currentLang}</span>
          </button>

          {langModalOpen && (
            <div style={s.modal}>
              <button style={s.modalOpt(currentLang === 'FR')} onClick={() => { setCurrentLang('FR'); setLangModalOpen(false); }}>FR</button>
              <button style={s.modalOpt(currentLang === 'US')} onClick={() => { setCurrentLang('US'); setLangModalOpen(false); }}>US</button>
            </div>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
